\begin{lemma}
For each nonnegative integer $n$, let $B_n$ be the $n$th Bell number, namely the number of partitions of an $n$-element set into nonempty subsets. For every positive integer $m$ and every prime $p$,
\[
B_{p^m}\equiv m+1\pmod p.
\]
\end{lemma}

